refentry.refsect1:
&reftitle.parameters;


  flag

   El estado a establecer. Por omisión, &true;.

  &reftitle.examples;

   Ejemplo de Yaf_Request_Abstract::setRouted


<?php
class ApiRouter extends Yaf_Route_Interface
{
    public function route(Yaf_Request_Abstract $request)
    {
        if (0 !== strpos($request->getRequestUri(), "/api/")) {
            return false;
        }

        $request->setControllerName("Api")
                ->setActionName("handle");

        // Impide que se ejecuten los enrutadores registrados después de este
        $request->setRouted();

        return true;
    }

    public function assemble(array $info, array $query = null) {}
}
?>
